for (const [id, extraRow] of Object.entries(historyUnitRows)) {
  if (tables[id]) {
    tables[id] = {
      title: `${extraRow[0]}與史料判讀對照表`,
      rows: [extraRow, ...tables[id].rows]
    };
  }
}

export const teachingTables = tables;
const esc = value => String(value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
export function knowledgePoints(u) {
  return u.concept.split(/。|；/).map(s=>s.trim()).filter(Boolean);
}
export function teachingFor(u) {
  const base = tables[u.id];
  if (base) {
    const pts = knowledgePoints(u);
    const unitSpecificRows = [
      ['本課核心判準', pts[0] ? `${pts[0]}。` : u.concept, `代表例證：${u.example}`],
      ['本課易錯防線', u.pitfall, `遷移檢核：${u.task}`]
    ];
    return {
      title: base.title.includes(u.title) ? base.title : `${u.title} · ${base.title}`,
      rows: [...base.rows, ...unitSpecificRows]
    };
  }
  return {title: `${u.title} · 概念、應用與界線對照`, rows:[
    ...knowledgePoints(u).map((point,i)=>['核心 '+(i+1),point,'試著用下方例題，說明這項概念如何影響判斷。']),
    ['應用情境',u.example,'先辨識已知條件，再對照上列概念。'],
    ['易錯界線',u.pitfall,'提出一個會犯此錯誤的例子，再改正理由。']
  ]};
}
function getRowIcon(label) {
  if (label.includes('核心判準') || label.includes('核心')) return '🎯';
  if (label.includes('易錯') || label.includes('防線') || label.includes('陷阱')) return '🛡️';
  if (label.includes('比') || label.includes('公式') || label.includes('算') || label.includes('數') || label.includes('量')) return '📐';
  if (label.includes('實驗') || label.includes('反應') || label.includes('細胞') || label.includes('器官') || label.includes('波')) return '🔬';
  if (label.includes('法') || label.includes('權') || label.includes('制度') || label.includes('責任') || label.includes('程序')) return '⚖️';
  if (label.includes('史') || label.includes('年代') || label.includes('文明') || label.includes('變革')) return '📜';
  if (label.includes('氣候') || label.includes('地') || label.includes('板塊') || label.includes('洋') || label.includes('環境')) return '🌍';
  if (label.includes('語') || label.includes('句') || label.includes('字') || label.includes('詞') || label.includes('閱讀') || label.includes('篇')) return '✍️';
  return '📌';
}

export function renderTeaching(u) {
 const t=teachingFor(u);
 const pts=knowledgePoints(u);
 return `<section class="teaching-notes" aria-label="逐點學習與比較表"><div class="teaching-notes-header"><div class="teaching-notes-title-wrap"><span class="teaching-badge">📊 108課綱核心知識點矩陣</span><h3>拆開理解，再連起來：${esc(u.title)}</h3></div><div class="knowledge-chips-row" role="list" aria-label="學習維度導覽"><span class="knowledge-chip" role="listitem">🎯 核心概念</span><span class="knowledge-chip" role="listitem">⚖️ 判準法則</span><span class="knowledge-chip" role="listitem">🔍 實證檢驗</span><span class="knowledge-chip" role="listitem">🛡️ 避坑防護</span></div></div><ol class="knowledge-list">${pts.map((p,i)=>`<li><span class="knowledge-point-tag">📌 知識要點 ${i+1}</span><strong>${esc(p)}。</strong></li>`).join('')}</ol><div class="table-wrap"><table class="teaching-table"><caption>${esc(t.title)}</caption><thead><tr><th scope="col">辨識重點</th><th scope="col">規則／條件</th><th scope="col">例子／檢查方法</th></tr></thead><tbody>${t.rows.map(row=>{const isCore=row[0].includes('核心判準');const isDefense=row[0].includes('易錯防線');const rowCls=isCore?' class="row-highlight-core"':(isDefense?' class="row-highlight-defense"':'');const icon=getRowIcon(row[0]);return `<tr${rowCls}>${row.map((v,i)=>i===0?`<th scope="row"><span class="row-icon" aria-hidden="true">${icon}</span> ${esc(v)}</th>`:`<td>${esc(v)}</td>`).join('')}</tr>`;}).join('')}</tbody></table></div><details class="worked-retrieval"><summary>先遮住講義：我能解釋「${esc(u.title)}」嗎？</summary><p>先口頭說出核心概念，再展開上表核對。最後完成這項遷移任務：</p><p>${esc(u.task)}</p><p class="subtle">能認出答案只是第一步；還要能說明理由、條件，以及何時不能套用。</p></details></section>`;
}
